"""Original editorial line drawings for the statistics catalogue.
Run with python3 scripts/generate-art.py. All coordinates share a 320 × 200 canvas.
"""
from pathlib import Path
from math import sin, cos, pi
OUT = Path(__file__).resolve().parents[1] / 'public' / 'art'

def path(d, **attrs):
    return '<path d="' + d + '" ' + ' '.join((f'''{k.replace('_', '-')}="{v}"''' for k, v in attrs.items())) + '/>'

def ellipse(x, y, rx, ry, **attrs):
    return f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" ' + ' '.join((f'''{k.replace('_', '-')}="{v}"''' for k, v in attrs.items())) + '/>'

def circle(x, y, r, **attrs):
    return ellipse(x, y, r, r, **attrs)

def rect(x, y, w, h, rx=0, **attrs):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" ' + ' '.join((f'''{k.replace('_', '-')}="{v}"''' for k, v in attrs.items())) + '/>'

def fine(d):
    return path(d, stroke_width='.65', opacity='.65')

def hatch(x, y, w, h, step=5):
    return ''.join((fine(f'M{x + i} {y}v{h}') for i in range(0, w, step)))

def group(s, transform):
    return f'<g transform="{transform}">{s}</g>'

def ground(x=60, y=169, w=200):
    return fine(f'M{x} {y}h{w}m{-w + 12} 4h{w - 42}m{-w + 52} 3h{w - 85}')

def leaf(x, y, angle=0, size=1):
    return group(path('M0 0C-17-2-23-17-22-28C-7-27 4-17 0 0Z') + fine('M0 0l-19-25m10 13l-10-2m14 8l-1-12'), f'translate({x} {y}) rotate({angle}) scale({size})')

def book(x, y, w=92, h=12):
    return path(f'M{x} {y}l{w - 10}-9 22 10v{h}l-{w - 10} 9-{22}-10Z M{x} {y}l22 10 {w - 10}-9M{x + 22} {y + 10}v{h}') + fine(f'M{x + 27} {y + 14}l{w - 20}-8m{-w + 20} 11l{w - 20}-8')

def windows(x, y, cols, rows, dx=15, dy=19):
    return ''.join((rect(x + c * dx, y + r * dy, 6, 9, stroke_width='.75') for r in range(rows) for c in range(cols)))
